<script setup lang="ts">import {ref,onMounted} from 'vue';import {request} from '../api/client';import type {Audit} from '../types/domain';import {useTask} from '../hooks/useTask';import PageHeading from '../components/common/PageHeading.vue';import ErrorNotice from '../components/common/ErrorNotice.vue';const rows=ref<Audit[]>([]),{error,perform}=useTask();async function load(){rows.value=await request<Audit[]>('/audit');}onMounted(()=>perform(load));</script><template><PageHeading index="06" title="每一次分析与交付，都留下记录" text="最近100次写入、审批与导出，包括被拒绝的权限操作。"><button class="outline" @click="perform(load)">刷新留痕 ↻</button></PageHeading><ErrorNotice :message="error" @retry="perform(load)"/><div class="table-wrap"><table><thead><tr><th>UTC时间</th><th>操作账号</th><th>动作</th><th>状态码</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td>{{r.created_at}}</td><td>{{r.actor}}</td><td>{{r.action}}</td><td :class="r.status_code<400?'positive':'warning'">{{r.status_code}}</td></tr></tbody></table></div></template>
